// The series region: (1 + mu) sigma <= 0.04 for mu < 20, 0.08 for 20 <= mu < 200 and 0.1 from
// mu = 200 on. The series converges more slowly for moderate mu than for large mu, which fixes the
// three cuts; measured against the 60-digit sums, the terms of order above 21 leave at most
// 1.4e-13 (order 4, relative to the largest component of the order) at the cuts.
static inline bool series_region(const double mu, const double sg) {
    return (1.0 + mu) * sg <= (mu >= 200.0 ? 0.1 : (mu >= 20.0 ? 0.08 : 0.04));
}

// s[k (k + 1) / 2 + q] = d^k S / dmu^(k-q) dsigma^q for k = 0..K, from the series. A term is
// a mu^j sigma^k. For mu >= 1 it is written a mu^(j-k) x^k with x = sigma mu, where j - k <= 2 and
// only the powers mu^2, mu, 1, 1/mu, ... occur, so that nothing overflows where the result does
// not; for mu < 1 the powers of mu and sigma are used as they are.
static inline void series_S(const double mu, const double sg, const int K, double* s) {
    const bool big = mu >= 1.0;
    const double x = sg * mu, mi = 1.0 / mu;
    double xpw[24], mpos[24], mneg[26];
    xpw[0] = 1.0; mpos[0] = 1.0; mneg[0] = 1.0;
    if (big) {
        for (int i = 1; i < 22; ++i) xpw[i] = xpw[i - 1] * x;
        for (int i = 1; i < 8; ++i) mpos[i] = mpos[i - 1] * mu;
        for (int i = 1; i < 26; ++i) mneg[i] = mneg[i - 1] * mi;
    } else {
        for (int i = 1; i < 22; ++i) xpw[i] = xpw[i - 1] * sg;       // sigma^i
        for (int i = 1; i < 24; ++i) mpos[i] = mpos[i - 1] * mu;     // mu^i
    }
    for (int k = 0; k <= K; ++k) {
        for (int q = 0; q <= k; ++q) {
            const int p = k - q;
            double tot = 0.0;
            for (int t = 0; t < SER_NT; ++t) {
                const int kk = SER_K[t], jj = SER_J[t];
                if (jj < p || kk < q) continue;
                const double fj = SER_FF[jj][p], fk = SER_FF[kk][q];
                if (big) {
                    // mu^(jj-p) sigma^(kk-q) = mu^e x^(kk-q), e = (jj-p) - (kk-q)
                    const int e = (jj - p) - (kk - q);
                    tot += SER_A[t] * fj * fk * xpw[kk - q] * (e >= 0 ? mpos[e] : mneg[-e]);
                } else {
                    tot += SER_A[t] * fj * fk * mpos[jj - p] * xpw[kk - q];
                }
            }
            s[k * (k + 1) / 2 + q] = tot;
        }
    }
}

